declare(strict_types=1);session_start();require __DIR__.'/bot.php';$c=cfg();if(empty($c['google_client_id'])||empty($c['google_client_secret']))die('Configure KEDDY_GOOGLE_CLIENT_ID and KEDDY_GOOGLE_CLIENT_SECRET first.');$state=bin2hex(random_bytes(24));$_SESSION['keddy_oauth_state']=$state;$url='https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query(['client_id'=>$c['google_client_id'],'redirect_uri'=>$c['redirect_uri'],'response_type'=>'code','scope'=>'https://www.googleapis.com/auth/youtube.force-ssl','access_type'=>'offline','prompt'=>'consent','state'=>$state]);header('Location: '.$url);exit;
